Definition cpx_fb (fbd fbs : Z) : Z := Z.lor (Z.land fbs 2) (Z.land (((2 * (fbd / 2)) mod 2 ^ 64 + 1) mod 2 ^ 64) 253).
Lemma cpx_fb_facts fbd fbs : 0 <= fbd < 256 -> 0 <= fbs < 256 ->
