Lemma u64_of_bytes (M : mem) a (bs : list byte) v :
  bs = word_to_le_bytes 8 (Z_to_bv 64 v) -> 0 <= a -> a + 8 <= 2 ^ 64 ->
  (forall i, 0 <= i < 8 -> exists b, (nth_error bs (Z.to_nat i) = Some (Z_to_bv 8 b) /\ 0 <= b < 256) /\ byte_at M (a + i) b) ->
  L5.u64_at RSEGS M a v.
Proof.
