Lemma TAIL (gk : list Z) (q fbd : Z) M6 model6 LK6 Aw6 cr6 (fx6 : FPState) R6 :
  In gk (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ->
  GM [gk :: D] [(q, 64)] M6 model6 LK6 Aw6 cr6 ->
  ablock_range L ar q 64 -> blocks_apart q 64 LBX -> fframes_apart q 64 (FF' ++ LK6) -> L5.defined M6 q 64 -> shadow_blk M6 q 64 ->
  PMSP.credit_keep cr cr6 (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
  0 <= fbd < 256 -> dhdr M6 fbd -> L5KA.zeros_at M6 (d / 8 + SB) 4 ->
  getr R6 (reg 2) = Z_to_bv 64 spc -> getr R6 (reg 3) = getr R (reg 3) -> getr R6 (reg 4) = getr R (reg 4) -> getr R6 (reg 27) = getr R (reg 27) ->
  getr R6 (reg 8) = Z_to_bv 64 sp -> getr R6 (reg 18) = Z_to_bv 64 F -> getr R6 (reg 23) = Z_to_bv 64 (F / 8 + 2147450880) -> getr R6 (reg 24) = Z_to_bv 64 F ->
  getr R6 (reg 10) = Z_to_bv 64 q -> getr R6 (reg 19) = Z_to_bv 64 s -> getr R6 (reg 20) = Z_to_bv 64 ((d + 24) / 8 + 2147450880) ->
